# ============================================================================
# MAIN FRAUD CHECK
# ============================================================================

@app.post("/check", response_model=FraudCheckResponse)
async def check_fraud(
    request: FraudCheckRequest,
    db: Session = Depends(get_db),
):
    # ── STEP 1: Rules Engine ──────────────────────────────────────────
    triggered_rules, rules_score = await app.state.rules_engine.evaluate(request, db)

    # ── STEP 2: ML Model ─────────────────────────────────────────────
    velocity_counts = app.state.velocity_rules.get_counts_for_ml(
        db,
        request.card.fingerprint,
        request.customer.ip_address,
        request.customer.id,
    )

    is_first_card_use = (
        db.query(FraudCheck)
        .filter(FraudCheck.card_fingerprint == request.card.fingerprint)
        .count()
    ) == 0

    exp_months = app.state.card_rules.get_exp_months_remaining(
        request.card.exp_month, request.card.exp_year
    )
    email_risk = app.state.amount_rules.get_email_domain_risk(request.customer.email)

    features = extract_features(
        request=request,
        velocity_counts=velocity_counts,
        exp_months_remaining=exp_months,
        is_first_card_use=is_first_card_use,
        email_domain_risk=email_risk,
    )

    ml_probability = app.state.ml_scorer.predict(features)
    ml_score_normalized = ml_probability * 100

    # ── STEP 3: Combine Scores ───────────────────────────────────────
    if settings.ml_model_enabled:
        final_score = int(
            rules_score * settings.rules_weight +
            ml_score_normalized * settings.ml_model_weight
        )
    else:
        final_score = rules_score

    final_score = min(final_score, 100)

    # ── STEP 4: Decision ─────────────────────────────────────────────
    if final_score <= settings.low_risk_threshold:
        risk_level = RiskLevel.LOW
        allowed = True
        review_required = False
        recommendation = "Allow transaction"
        block_reason = None

    elif final_score <= settings.medium_risk_threshold:
        risk_level = RiskLevel.MEDIUM
        allowed = True
        review_required = True
        recommendation = "Allow with monitoring"
        block_reason = None

    else:
        risk_level = RiskLevel.HIGH
        allowed = False
        review_required = False
        top_rule = max(
            (r for r in triggered_rules if r.triggered),
            key=lambda x: x.score_impact,
            default=None,
        )
        block_reason = top_rule.reason if top_rule else "High risk score"
        recommendation = f"Block: {block_reason}"

    # ── STEP 5: Save Fraud Check ──────────────────────────────────────
    check_id = f"fc_{uuid.uuid4().hex[:18]}"

    fraud_check = FraudCheck(
        id=check_id,
        payment_id=request.payment_id,
        merchant_id=request.merchant_id,
        amount=request.amount,
        currency=request.currency,
        card_last4=request.card.last4,
        card_brand=request.card.brand,
        card_fingerprint=request.card.fingerprint,
        card_exp_month=request.card.exp_month,
        card_exp_year=request.card.exp_year,
        customer_id=request.customer.id,
        customer_email=request.customer.email,
        ip_address=request.customer.ip_address,
        user_agent=request.customer.user_agent,
        risk_score=final_score,
        rules_score=rules_score,
        ml_score=ml_probability,
        risk_level=risk_level.value,
        allowed=allowed,
        block_reason=block_reason,
        triggered_rules=[
            {"rule": r.rule_name, "impact": r.score_impact, "reason": r.reason}
            for r in triggered_rules
            if r.triggered
        ],
        review_required=review_required,
    )
    db.add(fraud_check)

    # ── STEP 6: Save ML Training Sample ──────────────────────────────
    training_sample = MLTrainingSample(
        id=f"ts_{uuid.uuid4().hex[:18]}",
        fraud_check_id=check_id,
        payment_id=request.payment_id,
        amount=request.amount,
        hour_of_day=datetime.utcnow().hour,
        day_of_week=datetime.utcnow().weekday(),
        card_velocity_1h=velocity_counts.get("card_velocity_1h", 0),
        ip_velocity_1h=velocity_counts.get("ip_velocity_1h", 0),
        customer_tx_count=velocity_counts.get("customer_tx_count", 0),
        customer_failed_count=velocity_counts.get("customer_failed_count", 0),
        is_first_card_use=is_first_card_use,
        is_round_amount=request.amount >= 20000 and request.amount % 10000 == 0,
        is_micro_amount=request.amount < 100,
        email_domain_risk=email_risk,
        card_exp_months_remaining=exp_months,
    )
    db.add(training_sample)
    db.commit()

    logger.info(
        f"Fraud check: payment={request.payment_id} "
        f"score={final_score} allowed={allowed} "
        f"rules={rules_score} ml={ml_probability:.3f}"
    )

    return FraudCheckResponse(
        payment_id=request.payment_id,
        allowed=allowed,
        risk_score=final_score,
        risk_level=risk_level,
        rules_score=rules_score,
        ml_score=round(ml_probability, 4),
        triggered_rules=[r for r in triggered_rules if r.triggered],
        recommendation=recommendation,
        review_required=review_required,
        block_reason=block_reason,
    )


