@app.post("/blocklist/add")
async def add_to_blocklist(
    request: BlocklistAddRequest,
    db: Session = Depends(get_db),
):
    existing = (
        db.query(Blocklist)
        .filter(Blocklist.type == request.type, Blocklist.value == request.value.lower())
        .first()
    )
    if existing:
        return {"message": f"{request.value} already in blocklist", "id": existing.id}

    entry = Blocklist(
        id=f"bl_{uuid.uuid4().hex[:18]}",
        type=request.type,
        value=request.value.lower(),
        reason=request.reason,
        added_by=request.added_by,
        expires_at=request.expires_at,
    )
    db.add(entry)
    db.commit()
    return {
        "message": "Added to blocklist",
        "id": entry.id,
        "type": request.type,
        "value": request.value,
    }


@app.get("/blocklist")
async def list_blocklist(db: Session = Depends(get_db)):
    entries = db.query(Blocklist).order_by(Blocklist.created_at.desc()).all()
    return {
        "total": len(entries),
        "entries": [
            {
                "id": e.id,
                "type": e.type,
                "value": e.value,
                "reason": e.reason,
                "added_by": e.added_by,
                "expires_at": e.expires_at.isoformat() if e.expires_at else None,
                "created_at": e.created_at.isoformat(),
            }
            for e in entries
        ],
    }


@app.delete("/blocklist/{entry_id}")
async def remove_from_blocklist(entry_id: str, db: Session = Depends(get_db)):
    entry = db.query(Blocklist).filter(Blocklist.id == entry_id).first()
    if not entry:
        raise HTTPException(status_code=404, detail="Blocklist entry not found")
    db.delete(entry)
    db.commit()
    return {"message": "Removed from blocklist", "id": entry_id}


# ============================================================================
# FRAUD CONFIRMATION (for ML training)
# ============================================================================

@app.post("/confirm-fraud")
async def confirm_fraud(
    request: ConfirmFraudRequest,
    db: Session = Depends(get_db),
):
    sample = (
        db.query(MLTrainingSample)
        .filter(MLTrainingSample.fraud_check_id == request.fraud_check_id)
        .first()
    )
    if not sample:
        raise HTTPException(status_code=404, detail="Training sample not found")

    sample.is_fraud = request.is_fraud
    sample.confirmed_at = datetime.utcnow()
    db.commit()

    return {
        "message": "Fraud label saved for ML training",
        "fraud_check_id": request.fraud_check_id,
        "is_fraud": request.is_fraud,
    }


