@app.get("/history/{card_fingerprint}")
async def get_card_history(card_fingerprint: str, db: Session = Depends(get_db)):
    checks = (
        db.query(FraudCheck)
        .filter(FraudCheck.card_fingerprint == card_fingerprint)
        .order_by(FraudCheck.created_at.desc())
        .limit(20)
        .all()
    )
    return {
        "card_fingerprint": card_fingerprint,
        "total_checks": len(checks),
        "blocked_count": sum(1 for c in checks if not c.allowed),
        "average_risk_score": sum(c.risk_score for c in checks) / len(checks) if checks else 0,
        "history": [
            {
                "payment_id": c.payment_id,
                "risk_score": c.risk_score,
                "allowed": c.allowed,
                "risk_level": c.risk_level,
                "triggered_rules": c.triggered_rules,
                "created_at": c.created_at.isoformat(),
            }
            for c in checks
        ],
    }


@app.get("/stats")
async def get_stats(db: Session = Depends(get_db)):
    total = db.query(FraudCheck).count()
    blocked = db.query(FraudCheck).filter(~FraudCheck.allowed).count()
    reviewed = db.query(FraudCheck).filter(FraudCheck.review_required).count()
    return {
        "total_checks": total,
        "allowed": total - blocked,
        "blocked": blocked,
        "review_required": reviewed,
        "block_rate": round(blocked / total * 100, 2) if total else 0,
    }
